(433, 7, 'reading', 'What is the bank changing?', '["Its weekend hours", "Its fees", "Its name", "Its location"]', 0, 'Ngân hàng đổi giờ mở cửa cuối tuần.', 'comprehension', 'finance', 629, 'CITYBANK NOTICE\n\nStarting next month, our branches will open on Saturday mornings from 8 a.m. to noon. Sunday hours remain unchanged. Our mobile app is available 24 hours for transfers and bill payments. Thank you for banking with us!'),
(434, 7, 'reading', 'When is the bank open on Saturdays?', '["8 a.m. to noon", "9 a.m. to 5 p.m.", "Closed", "All day"]', 0, '"...on Saturday mornings from 8 a.m. to noon".', 'comprehension', 'finance', 629, 'CITYBANK NOTICE\n\nStarting next month, our branches will open on Saturday mornings from 8 a.m. to noon. Sunday hours remain unchanged. Our mobile app is available 24 hours for transfers and bill payments. Thank you for banking with us!'),
