(436, 7, 'reading', 'What is for rent?', '["A second-floor office", "A house", "A car", "A warehouse"]', 0, 'Cho thuê văn phòng tầng 2, 80m².', 'comprehension', 'office', 630, 'OFFICE FOR RENT\n\nBright second-floor office, 80 square meters, in the city center. Monthly rent $1,200 including electricity and cleaning. Available from September 1st. Contact Mr. Nam at 091-234-5678 for a viewing.'),
(437, 7, 'reading', 'How much is the monthly rent?', '["$1,200", "$800", "$2,000", "$1,000"]', 0, '"Monthly rent $1,200...".', 'comprehension', 'office', 630, 'OFFICE FOR RENT\n\nBright second-floor office, 80 square meters, in the city center. Monthly rent $1,200 including electricity and cleaning. Available from September 1st. Contact Mr. Nam at 091-234-5678 for a viewing.'),
(438, 7, 'reading', 'When is it available?', '["September 1st", "August 1st", "Immediately", "Next year"]', 0, '"Available from September 1st".', 'comprehension', 'office', 630, 'OFFICE FOR RENT\n\nBright second-floor office, 80 square meters, in the city center. Monthly rent $1,200 including electricity and cleaning. Available from September 1st. Contact Mr. Nam at 091-234-5678 for a viewing.')
